api.get('/posts', async (ctx) => {
  return ctx.json({ posts: [] });
});

// Nested groups
const admin = api.group('/admin');

admin.get('/stats', async (ctx) => {
  // Route: /api/v1/admin/stats
  return ctx.json({ stats: {} });
});

// Groups can have their own middleware
